#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int cnt[26] = {0};
    for (char c : s) cnt[c - 'a']++;
    for (int i = 0; i < 26; i++)
        if (cnt[i]) cout << (char)('a' + i) << ' ' << cnt[i] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string date;
    getline(cin, date);
    istringstream iss(date);
    string tok;
    vector<int> parts;
    while (getline(iss, tok, '-')) parts.push_back(stoi(tok));
    cout << parts[0] << ' ' << parts[1] << ' ' << parts[2] << '\n';

    string line, w;
    getline(cin, line);
    istringstream ws(line);
    vector<string> words;
    while (ws >> w) words.push_back(w);
    cout << words.size() << '\n';
    string joined;
    for (size_t i = 0; i < words.size(); i++) {
        string up = words[i];
        for (char &c : up) c = (char)toupper(c);
        if (i) joined += '-';
        joined += up;
    }
    cout << joined << '\n';
    return 0;
}
